package damage.engine.client.gui;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import damage.engine.DamageEngineMeta;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.components.Tooltip;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

public class HomeScreen extends Screen {
    private final Screen parent;
    private int buttonsLeftX;

    private enum UpdateState { IDLE, CHECKING, LATEST, OUTDATED, ERROR }

    private UpdateState updateState = UpdateState.IDLE;
    private String updateFoundVersion = "";
    private boolean updateChecked = false;

    /** 按当前运行的 MC 版本与加载器拼查询串，避免升版本时漏改导致检查失败。 */
    private static String updateUrl() {
        return "https://api.modrinth.com/v2/project/damage-engine/version?game_versions=%5B%22"
            + DamageEngineMeta.mcVersion() + "%22%5D&loaders=%5B%22" + DamageEngineMeta.PLATFORM + "%22%5D";
    }
    private static final HttpClient HTTP_CLIENT = HttpClient.newBuilder()
        .connectTimeout(Duration.ofSeconds(5))
        .build();

    public HomeScreen(Screen parent) {
        super(Component.translatable("title.damage-engine.home"));
        this.parent = parent;
    }

    @Override
    protected void init() {
        this.clearWidgets();

        int centerX = this.width / 2;
        int buttonWidth = 100;
        int buttonHeight = 22;
        int buttonSpacing = 8;
        int totalButtonsWidth = buttonWidth * 2 + buttonSpacing;

        // Buttons placed lower on screen
        int buttonY = this.height / 2 + 30;

        // Left edge of the centered button row; the title above is aligned to it
        this.buttonsLeftX = centerX - totalButtonsWidth / 2;

        this.addRenderableWidget(new StyledButton(
            this.buttonsLeftX, buttonY,
            buttonWidth, buttonHeight,
            Component.translatable("button.damage-engine.settings"),
            () -> this.minecraft.setScreen(new DamageConfigScreen(this))
        ));

        // Config Management button
        this.addRenderableWidget(new StyledButton(
            this.buttonsLeftX + buttonWidth + buttonSpacing, buttonY,
            buttonWidth, buttonHeight,
            Component.translatable("button.damage-engine.config_management"),
            () -> this.minecraft.setScreen(new ProfileManagerScreen(this))
        ));

        // Auto-check for updates once on entering the home screen
        // (init() re-runs on window resize; guard so we don't re-request every time)
        if (!updateChecked) {
            updateChecked = true;
            this.checkForUpdates();
        }
    }

    private void checkForUpdates() {
        if (updateState == UpdateState.CHECKING) return;
        updateState = UpdateState.CHECKING;

        Thread thread = new Thread(() -> {
            String latest = null;
            try {
                HttpRequest request = HttpRequest.newBuilder(URI.create(updateUrl()))
                    .timeout(Duration.ofSeconds(10))
                    .header("User-Agent", "damage-engine/" + DamageEngineMeta.VERSION)
                    .GET()
                    .build();
                HttpResponse<String> response = HTTP_CLIENT.send(request, HttpResponse.BodyHandlers.ofString());
                if (response.statusCode() == 200) {
                    JsonArray array = JsonParser.parseString(response.body()).getAsJsonArray();
                    if (!array.isEmpty()) {
                        // Only consider versions for the current loader platform (Fabric/NeoForge
                        // releases share the same project on Modrinth). The URL already filters by
                        // loaders; this is a defensive second check.
                        for (int i = 0; i < array.size(); i++) {
                            JsonObject entry = array.get(i).getAsJsonObject();
                            if (!hasLoader(entry, DamageEngineMeta.PLATFORM)) continue;
                            if (entry.has("version_number") && !entry.get("version_number").isJsonNull()) {
                                String v = entry.get("version_number").getAsString();
                                if (latest == null || compareVersions(v, latest) > 0) {
                                    latest = v;
                                }
                            }
                        }
                    }
                }
            } catch (Exception ignored) {
                // network / parse failure -> error state
            }

            String found = latest;
            Minecraft.getInstance().execute(() -> {
                if (found == null || found.isEmpty()) {
                    updateState = UpdateState.ERROR;
                } else if (compareVersions(found, DamageEngineMeta.VERSION) > 0) {
                    updateFoundVersion = found;
                    updateState = UpdateState.OUTDATED;
                } else {
                    updateState = UpdateState.LATEST;
                }
            });
        });
        thread.setDaemon(true);
        thread.start();
    }

    private static boolean hasLoader(JsonObject entry, String platform) {
        if (!entry.has("loaders") || entry.get("loaders").isJsonNull()) {
            return true; // No loader info: accept defensively
        }
        JsonArray loaders = entry.get("loaders").getAsJsonArray();
        for (int i = 0; i < loaders.size(); i++) {
            var el = loaders.get(i);
            if (el.isJsonPrimitive() && platform.equals(el.getAsString())) {
                return true;
            }
        }
        return false;
    }

    private static int compareVersions(String a, String b) {
        // Strip pre-release/build metadata suffixes (e.g. "1.4.3-fabric", "1.4.3+build5")
        // so pure version numbers compare numerically
        String[] pa = stripSuffix(a).split("\\.");
        String[] pb = stripSuffix(b).split("\\.");
        int n = Math.max(pa.length, pb.length);
        for (int i = 0; i < n; i++) {
            String sa = i < pa.length ? pa[i] : "";
            String sb = i < pb.length ? pb[i] : "";
            // Missing segments count as 0, so "1.4.3" == "1.4.3.0" and "1.4" == "1.4.0"
            Integer na = sa.isEmpty() ? 0 : parseNumOrNull(sa);
            Integer nb = sb.isEmpty() ? 0 : parseNumOrNull(sb);
            if (na != null && nb != null) {
                if (!na.equals(nb)) return Integer.compare(na, nb);
            } else {
                int cmp = sa.compareTo(sb);
                if (cmp != 0) return cmp;
            }
        }
        return 0;
    }

    private static String stripSuffix(String s) {
        int idx = s.indexOf('-');
        if (idx < 0) idx = s.indexOf('+');
        return idx < 0 ? s : s.substring(0, idx);
    }

    private static Integer parseNumOrNull(String s) {
        if (s.isEmpty()) return null;
        try {
            return Integer.parseInt(s);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    @Override
    public void extractRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float delta) {
        // 1.21.11: in-game background blur is applied once by the render pipeline;
        // calling renderBackground() here would blur twice and crash.
        // On the main menu (no world) draw the panorama background without blur.
        if (this.minecraft != null && this.minecraft.level == null) {
            this.extractPanorama(guiGraphics, delta);
        }

        int centerX = this.width / 2;
        int titleY = this.height / 4;
        // Title left-aligned to the left edge of the centered button row below
        int titleLeftX = this.buttonsLeftX;

        // Bigger "Damage Engine" title with scale + scan overlay on top
        guiGraphics.pose().pushMatrix();
        float titleScale = 2.0f;
        guiGraphics.pose().scale(titleScale, titleScale);
        String titleText = Component.translatable("title.damage-engine.home").getString();
        int scaledX = (int)(titleLeftX / titleScale);
        int scaledY = (int)(titleY / titleScale);
        guiGraphics.text(this.font, titleText, scaledX, scaledY, 0xFFFFFFFF);
        guiGraphics.pose().popMatrix();

        // "Developed by mitama" - left aligned below title
        String devText = Component.translatable("text.damage-engine.developed_by").getString();
        int greenColor = 0xFFB5F0C6;
        guiGraphics.text(this.font, devText, titleLeftX, titleY + (int)(this.font.lineHeight * titleScale) + 6, greenColor);

        // Update status text at the bottom of the screen
        if (updateState != UpdateState.IDLE) {
            String statusText = "";
            int statusColor = 0xFFA0A0A0; // grey
            switch (updateState) {
                case CHECKING -> {
                    statusText = Component.translatable("text.damage-engine.checking_update").getString();
                    statusColor = 0xFFA0A0A0; // grey
                }
                case LATEST -> {
                    statusText = Component.translatable("text.damage-engine.update_latest", DamageEngineMeta.VERSION).getString();
                    statusColor = greenColor; // green
                }
                case OUTDATED -> {
                    statusText = Component.translatable("text.damage-engine.update_available", updateFoundVersion, DamageEngineMeta.VERSION).getString();
                    statusColor = 0xFFFFB74D; // orange
                }
                case ERROR -> {
                    statusText = Component.translatable("text.damage-engine.update_check_failed").getString();
                    statusColor = 0xFFFF7E7E; // red
                }
            }
            guiGraphics.centeredText(this.font, statusText, centerX, this.height - 30, statusColor);
        }

        // Render widgets + tooltips manually (avoid super.render() blur)
        for (var child : this.children()) {
            if (child instanceof AbstractWidget w) {
                w.extractRenderState(guiGraphics, mouseX, mouseY, delta);
                // Tooltip is rendered automatically by the widget system in 1.21.11
            }
        }
    }

    @Override
    public void onClose() {
        this.minecraft.setScreen(parent);
    }

    private static class StyledButton extends AbstractWidget {
        private final Runnable onPress;

        public StyledButton(int x, int y, int width, int height, Component message, Runnable onPress) {
            super(x, y, width, height, message);
            this.onPress = onPress;
        }

        @Override
        public boolean mouseClicked(net.minecraft.client.input.MouseButtonEvent event, boolean bl) {
            if (this.active && this.visible && event.button() == 0) {
                if (this.isMouseOver(event.x(), event.y())) {
                    this.playDownSound(Minecraft.getInstance().getSoundManager());
                    this.onPress.run();
                    return true;
                }
            }
            return false;
        }

        @Override
        protected void extractWidgetRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float delta) {
            if (this.active && isHovered()) guiGraphics.requestCursor(DamageConfigScreen.CURSOR_HAND);
            int bgColor = this.active ? 0x20000000 : 0x10000000;
            guiGraphics.fill(getX(), getY(), getX() + getWidth(), getY() + getHeight(), bgColor);

            int borderColor;
            if (!this.active) {
                borderColor = 0xFF404040;
            } else if (isHovered()) {
                borderColor = 0xFFFFFFFF;
            } else {
                borderColor = 0xFFA0A0A0;
            }
            int x = getX(); int y = getY(); int w = getWidth(); int h = getHeight();
            guiGraphics.fill(x, y, x + w, y + 1, borderColor);
            guiGraphics.fill(x, y + h - 1, x + w, y + h, borderColor);
            guiGraphics.fill(x, y, x + 1, y + h, borderColor);
            guiGraphics.fill(x + w - 1, y, x + w, y + h, borderColor);

            int textColor = this.active ? 0xFFFFFFFF : 0xFF808080;
            guiGraphics.centeredText(Minecraft.getInstance().font, getMessage(), getX() + getWidth() / 2, getY() + (getHeight() - 8) / 2, textColor);
        }

        @Override
        protected void updateWidgetNarration(NarrationElementOutput builder) {
            this.defaultButtonNarrationText(builder);
        }
    }
}

package damage.engine.client.gui;

import damage.engine.client.gui.config.StyledButton;

import anima.api.AnimaApi;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

/**
 * 「动画编辑器需要专用配置世界」提示页。
 * <p>
 * 编辑器里的世界预览（真 3D 文字、粒子、坐标系）只在 Anima 的专用配置世界中渲染，而那个世界
 * 只能从主菜单进（{@code ConfigWorldLauncher.launch} 在已有世界内是空操作）。所以门槛由 DE 自己写：
 * 确认后调 {@link AnimaApi#enterConfigWorld(Screen)} 进去，进去之后再打开一次配置界面就能用上世界预览。
 */
public class ConfigWorldNeededScreen extends Screen {
    private final Screen settingsScreen;
    private final Minecraft mcl = Minecraft.getInstance();

    public ConfigWorldNeededScreen(Screen settingsScreen) {
        super(Component.translatable("text.damage-engine.config_world_title"));
        this.settingsScreen = settingsScreen;
    }

    @Override
    protected void init() {
        this.clearWidgets();
        int centerX = this.width / 2;
        int buttonY = this.height / 2 + 20;

        // Cancel (left) — back to the settings screen
        this.addRenderableWidget(new StyledButton(centerX - 105, buttonY, 100, 20,
            Component.translatable("gui.cancel").withColor(0xFFFC887E),
            () -> mcl.setScreen(settingsScreen)));

        // Confirm (right) — enter the dedicated preview world
        this.addRenderableWidget(new StyledButton(centerX + 5, buttonY, 100, 20,
            Component.translatable("button.damage-engine.enter_config_world").withColor(0xFFB7F3C8),
            () -> AnimaApi.enterConfigWorld(settingsScreen)));
    }

    @Override
    public void extractRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float delta) {
        // 1.21.11: in-game background blur is applied once by the render pipeline;
        // calling renderBackground() here would blur twice and crash.
        if (this.minecraft != null && this.minecraft.level == null) {
            this.extractPanorama(guiGraphics, delta);
        }

        // Hint text, wrapped to 300px and centred
        var lines = this.font.split(Component.translatable("text.damage-engine.config_world_needed"), 300);
        int y = this.height / 2 - 45;
        for (var line : lines) {
            guiGraphics.text(this.font, line, this.width / 2 - this.font.width(line) / 2, y, 0xFFFFFFFF);
            y += 12;
        }

        // Render widgets manually (avoid super.render() blur)
        for (var child : this.children()) {
            if (child instanceof net.minecraft.client.gui.components.Renderable r) {
                r.extractRenderState(guiGraphics, mouseX, mouseY, delta);
            }
        }
    }

    @Override
    public void onClose() {
        mcl.setScreen(settingsScreen);
    }
}

package damage.engine.client.gui;

import damage.engine.client.gui.config.StyledButton;

import damage.engine.DamageEngineConfig;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

/**
 * Custom-styled confirmation dialog for unsaved changes.
 */
public class ConfirmExitScreen extends Screen {
    private final Screen settingsScreen;
    private final Screen parent;
    private final DamageEngineConfig config;
    private final Minecraft mcl;

    public ConfirmExitScreen(Screen settingsScreen, Screen parent, DamageEngineConfig config) {
        super(Component.translatable("text.damage-engine.unsaved_changes_title"));
        this.settingsScreen = settingsScreen;
        this.parent = parent;
        this.config = config;
        this.mcl = Minecraft.getInstance();
    }

    @Override
    protected void init() {
        this.clearWidgets();
        int centerX = this.width / 2;
        int buttonY = this.height / 2 + 20;

        // Cancel button (left) - returns to settings
        this.addRenderableWidget(new StyledButton(centerX - 105, buttonY, 100, 20,
            Component.translatable("gui.cancel").withColor(0xFFFC887E),
            () -> mcl.setScreen(settingsScreen)));

        // Confirm button (right) - discards changes and exits
        this.addRenderableWidget(new StyledButton(centerX + 5, buttonY, 100, 20,
            Component.translatable("gui.confirm").withColor(0xFFB7F3C8),
            () -> {
                config.load();
                mcl.setScreen(parent);
            }));
    }

    @Override
    public void extractRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float delta) {
        // 1.21.11: in-game background blur is applied once by the render pipeline;
        // calling renderBackground() here would blur twice and crash.
        if (this.minecraft != null && this.minecraft.level == null) {
            this.extractPanorama(guiGraphics, delta);
        }

        String msg = Component.translatable("text.damage-engine.unsaved_changes").getString();
        guiGraphics.centeredText(this.font, msg, this.width / 2, this.height / 2 - 25, 0xFFFFFFFF);

        // Render widgets manually (avoid super.render() blur)
        for (var child : this.children()) {
            if (child instanceof net.minecraft.client.gui.components.Renderable r) {
                r.extractRenderState(guiGraphics, mouseX, mouseY, delta);
            }
        }
    }

    @Override
    public void onClose() {
        mcl.setScreen(settingsScreen);
    }
}

package damage.engine.client.gui;

import damage.engine.DamageEngineConfig;
import net.minecraft.util.Util;import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class ProfileManagerScreen extends Screen {
    private final Screen parent;
    private String selectedProfile;
    private final List<String> profiles = new ArrayList<>();

    public ProfileManagerScreen(Screen parent) {
        super(Component.translatable("title.damage-engine.profile_manager"));
        this.parent = parent;
        this.selectedProfile = DamageEngineConfig.getCurrentProfile();
    }

    @Override
    protected void init() {
        this.clearWidgets();
        profiles.clear();
        profiles.addAll(DamageEngineConfig.getProfileNames());

        int listStartY = 45;
        int entryHeight = 22;
        int listWidth = 200;
        int listX = this.width / 2 - listWidth / 2;

        for (int i = 0; i < profiles.size(); i++) {
            String profileName = profiles.get(i);
            boolean isSelected = profileName.equals(selectedProfile);
            int entryY = listStartY + i * (entryHeight + 2);

            this.addRenderableWidget(new ProfileButton(
                listX, entryY, listWidth, entryHeight,
                profileName, isSelected,
                () -> {
                    selectedProfile = profileName;
                    this.init();
                }
            ));
        }

        int buttonWidth = 80;
        int buttonY = this.height - 35;
        this.addRenderableWidget(new StyledButton(
            this.width - buttonWidth - 10, buttonY, buttonWidth, 20,
            Component.translatable("gui.done").withColor(0xFFB5F0C6),
            () -> {
                if (selectedProfile != null) {
                    String current = DamageEngineConfig.getCurrentProfile();
                    if (!selectedProfile.equals(current)) {
                        // 切换配置:先把当前设置存回它自己的文件,再从磁盘载入目标配置的内容。
                        // 注意不能反向 save()——那只是改了个"当前配置名",既不会载入目标配置的数值,
                        // 还会把当前设置覆盖进目标配置文件,导致看起来"没切换"且目标配置被冲掉。
                        DamageEngineConfig.getInstance().save();
                        DamageEngineConfig.getInstance().load(selectedProfile);
                    } else {
                        DamageEngineConfig.getInstance().save();
                    }
                }
                this.minecraft.setScreen(parent);
            }
        ));

        // Open config folder button
        this.addRenderableWidget(new StyledButton(
            this.width - buttonWidth * 2 - 20, buttonY, buttonWidth, 20,
            Component.translatable("button.damage-engine.open_config_folder"),
            () -> {
                File profilesDir = DamageEngineConfig.getProfilesDir().toFile();
                if (!profilesDir.exists()) {
                    profilesDir.mkdirs();
                }
                Util.getPlatform().openFile(profilesDir);
            }
        ));
    }

    @Override
    public void extractRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float delta) {
        // 1.21.11: in-game background blur is applied once by the render pipeline;
        // calling renderBackground() here would blur twice and crash.
        if (this.minecraft != null && this.minecraft.level == null) {
            this.extractPanorama(guiGraphics, delta);
        }

        String titleText = Component.translatable("title.damage-engine.profile_manager").getString();
        guiGraphics.centeredText(this.font, titleText, this.width / 2, 15, 0xFFFFFFFF);

        // Render widgets manually (avoid super.render() blur); tooltips are rendered
        // automatically by the widget system in 1.21.11
        for (var child : this.children()) {
            if (child instanceof AbstractWidget w) {
                w.extractRenderState(guiGraphics, mouseX, mouseY, delta);
            }
        }
    }

    @Override
    public void onClose() {
        this.minecraft.setScreen(parent);
    }

    private static class ProfileButton extends AbstractWidget {
        private final String profileName;
        private final boolean isSelected;
        private final Runnable onPress;

        public ProfileButton(int x, int y, int width, int height, String profileName, boolean isSelected, Runnable onPress) {
            super(x, y, width, height, Component.literal(profileName));
            this.profileName = profileName;
            this.isSelected = isSelected;
            this.onPress = onPress;
        }

        @Override
        public boolean mouseClicked(net.minecraft.client.input.MouseButtonEvent event, boolean bl) {
            if (this.active && this.visible && event.button() == 0 && this.isMouseOver(event.x(), event.y())) {
                this.playDownSound(Minecraft.getInstance().getSoundManager());
                this.onPress.run();
                return true;
            }
            return false;
        }

        @Override
        protected void extractWidgetRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float delta) {
            if (isHovered()) guiGraphics.requestCursor(DamageConfigScreen.CURSOR_HAND);
            int x = getX(); int y = getY(); int w = getWidth(); int h = getHeight();

            int bgColor = isHovered() ? 0x30FFFFFF : 0x10000000;
            guiGraphics.fill(x, y, x + w, y + h, bgColor);

            // Border for selected
            if (isSelected) {
                guiGraphics.fill(x, y, x + w, y + 1, 0xFFB5F0C6);
                guiGraphics.fill(x, y + h - 1, x + w, y + h, 0xFFB5F0C6);
                guiGraphics.fill(x, y, x + 1, y + h, 0xFFB5F0C6);
                guiGraphics.fill(x + w - 1, y, x + w, y + h, 0xFFB5F0C6);
            }

            int color = isSelected ? 0xFFB5F0C6 : 0xFFFFFFFF;
            guiGraphics.text(Minecraft.getInstance().font, profileName, x + 10, y + (h - 8) / 2, color);

            if (isSelected) {
                guiGraphics.text(Minecraft.getInstance().font, "✓", x + w - 20, y + (h - 8) / 2, 0xFFB5F0C6);
            }
        }

        @Override
        protected void updateWidgetNarration(NarrationElementOutput builder) {
            this.defaultButtonNarrationText(builder);
        }
    }

    private static class StyledButton extends AbstractWidget {
        private final Runnable onPress;

        public StyledButton(int x, int y, int width, int height, Component message, Runnable onPress) {
            super(x, y, width, height, message);
            this.onPress = onPress;
        }

        @Override
        public boolean mouseClicked(net.minecraft.client.input.MouseButtonEvent event, boolean bl) {
            if (this.active && this.visible && event.button() == 0) {
                if (this.isMouseOver(event.x(), event.y())) {
                    this.playDownSound(Minecraft.getInstance().getSoundManager());
                    this.onPress.run();
                    return true;
                }
            }
            return false;
        }

        @Override
        protected void extractWidgetRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float delta) {
            if (isHovered()) guiGraphics.requestCursor(DamageConfigScreen.CURSOR_HAND);
            guiGraphics.fill(getX(), getY(), getX() + getWidth(), getY() + getHeight(), 0x20000000);

            int borderColor = isHovered() ? 0xFFFFFFFF : 0xFFA0A0A0;
            int x = getX(); int y = getY(); int w = getWidth(); int h = getHeight();
            guiGraphics.fill(x, y, x + w, y + 1, borderColor);
            guiGraphics.fill(x, y + h - 1, x + w, y + h, borderColor);
            guiGraphics.fill(x, y, x + 1, y + h, borderColor);
            guiGraphics.fill(x + w - 1, y, x + w, y + h, borderColor);

            guiGraphics.centeredText(Minecraft.getInstance().font, getMessage(), getX() + getWidth() / 2, getY() + (getHeight() - 8) / 2, 0xFFFFFFFF);
        }

        @Override
        protected void updateWidgetNarration(NarrationElementOutput builder) {
            this.defaultButtonNarrationText(builder);
        }
    }
}

package damage.engine.compat.modmenu;

import com.terraformersmc.modmenu.api.ConfigScreenFactory;
import com.terraformersmc.modmenu.api.ModMenuApi;
import damage.engine.client.gui.HomeScreen;

public class ModMenuIntegration implements ModMenuApi {
    @Override
    public ConfigScreenFactory<?> getModConfigScreenFactory() {
        return parent -> new HomeScreen(parent);
    }
}

package damage.engine;

/**
 * Version metadata shared by both loader entrypoints.
 * Keep in sync with gradle.properties (mod_version).
 */
public final class DamageEngineMeta {
    public static final String VERSION = "2.2.2";

    /** Current loader platform: "fabric" or "neoforge". Detected at runtime via reflection. */
    public static final String PLATFORM;

    /**
     * 当前运行的 Minecraft 版本(如 "26.1.2")。版本检查要用它去匹配 Modrinth 的
     * game_versions，写死会在升版本时漏改，所以统一从运行时取。
     */
    public static String mcVersion() {
        return net.minecraft.SharedConstants.getCurrentVersion().name();
    }

    static {
        String platform = "neoforge";
        try {
            Class.forName("net.fabricmc.loader.api.FabricLoader");
            platform = "fabric";
        } catch (ClassNotFoundException ignored) {
            // NeoForge: fabric-loader is not present
        }
        PLATFORM = platform;
    }

    private DamageEngineMeta() {}
}

